const $ = (q, root = document) => root.querySelector(q);
const paths = {
 sparkle:'M12 2v20M2 12h20M5 5l14 14M5 19 19 5', home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z', heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z', route:'M6 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6Zm12 12a3 3 0 1 0 0 6 3 3 0 0 0 0-6ZM6 9v5a4 4 0 0 0 4 4h5M9 6h5a4 4 0 0 1 4 4v5', file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6', chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 0 1-1-5 9 9 0 0 1 18 0ZM8 10h8M8 14h5', arrow:'M5 12h14m-5-5 5 5-5 5', chevron:'m9 5 7 7-7 7', check:'m5 12 4 4L19 6', calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 2v6M17 2v6M3 11h18M7 15h3M14 15h3', clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z', video:'M3 5h12v14H3zM15 9l6-3v12l-6-3', shield:'m12 2 8 3v6c0 5-4 8-8 11-4-3-8-6-8-11V5zM8 11l3 3 5-6', info:'M12 10v7M12 6v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z', user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-3a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v3', doctor:'M6 3v6a6 6 0 0 0 12 0V3M4 3h4M16 3h4M12 15v2a4 4 0 0 0 8 0v-3M22 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z', bell:'M18 8a6 6 0 0 0-12 0c0 7-3 8-3 9h18c0-1-3-2-3-9ZM9 21h6', access:'M12 3a1.5 1.5 0 1 1 0 .1M4 8h16M12 7v7M8 22l4-8 4 8', menu:'M3 6h18M3 12h18M3 18h18', close:'m6 6 12 12M6 18 18 6', scan:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M8 12h8M12 8v8', chart:'M4 3v17h17M8 15V9M13 15V5M18 15v-5', users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3M16 4a4 4 0 0 1 0 8M18 14a5 5 0 0 1 4 5v2', search:'M16 16l5 5M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0Z', download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5', upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5', location:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z', leaf:'M20 3c-11-2-18 3-15 12s17 7 15-12ZM4 21 16 9', lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4', globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c5 6 5 14 0 20-5-6-5-14 0-20', bolt:'m13 2-9 12h7l-1 8 10-13h-7z', external:'M14 3h7v7M21 3 10 14M10 3H3v18h18v-7'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.sparkle}"/></svg>`;
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {role:'patient',view:'overview',health:null,consent:false,messages:[],reminder:false,reviewed:new Set(),scanPrior:false,overlay:true,selected:'CX-1042',filter:'all',search:'',agent:'guide',report:null,followups:{}};
const patients = [
 {id:'CX-1042',name:'Aino Lehtinen',age:58,type:'Lung',region:'Pirkanmaa',priority:'Priority review',reason:'Interval change on example imaging',initials:'AL',status:'Awaiting review'},
 {id:'CX-1043',name:'Mika Korhonen',age:63,type:'Colorectal',region:'Lapland',priority:'Routine review',reason:'Referral information ready',initials:'MK',status:'Referral received'},
 {id:'CX-1044',name:'Sara Niemi',age:46,type:'Breast',region:'Uusimaa',priority:'Priority review',reason:'Follow-up requires confirmation',initials:'SN',status:'Follow-up due'},
 {id:'CX-1045',name:'Olli Laine',age:69,type:'Prostate',region:'North Savo',priority:'Routine review',reason:'Specialist appointment requested',initials:'OL',status:'Pathway review'}
];
const patientNav = [['overview','home','My overview'],['health','heart','Health check'],['pathway','route','My care pathway'],['records','file','My records'],['messages','chat','Messages'],['agents','sparkle','AI care guide']];
const careNav = [['overview','home','Workspace'],['patients','users','Patient worklist'],['scan','scan','Imaging review'],['reports','file','Reports'],['analytics','chart','Quality & equity'],['agents','sparkle','AI workspace']];
const viewTitles = {overview:'Overview',health:'Health check',pathway:'Care pathway',records:'Records & preferences',messages:'Care team messages',patients:'Patient worklist',scan:'Imaging review',reports:'Clinical reports',analytics:'Quality & equity',agents:'AI workspace',platform:'The Candex approach'};
const goButton = (view,text,primary=false,role=state.role) => `<button class="${primary?'button':'text-btn'}" data-go="${role}/${view}">${text}${icon('arrow')}</button>`;
const badge = (text,cls='') => `<span class="badge ${cls}">${text}</span>`;
const demoNotice = (text='Interactive concept · All patient records, findings and metrics are fictional. No medical services are connected.') => `<div class="demo-banner">${icon('info')}<span>${text}</span></div>`;
function heading(title,sub,eyebrow='',extra=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 tabindex="-1" id="page-title">${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function getRoute(){const [r,v]=location.hash.replace('#','').split('/');state.role=r==='care'?'care':'patient';state.view=Object.hasOwn(viewTitles,v)?v:'overview';}
function navigate(route){if(location.hash===`#${route}`){getRoute();render(true);}else location.hash=route;}
function render(focus=false){
 const care=state.role==='care';const nav=care?careNav:patientNav;
 document.title=`${viewTitles[state.view]} · Candex`;
 $('#app').innerHTML=`<aside class="sidebar" id="sidebar" aria-label="Main navigation"><a class="brand" href="#${state.role}/overview" aria-label="Candex home">${icon('sparkle')}candex<span class="brand-period">.</span></a><div class="brand-caption">No patient left behind</div><p class="nav-label">${care?'Clinical workspace':'Your health, connected'}</p><nav class="nav-list">${nav.map(([v,i,t])=>`<button class="nav-item ${state.view===v?'active':''}" data-go="${state.role}/${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${t}${v==='messages'?'<span class="nav-count">1</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item concept-link ${state.view==='platform'?'active':''}" data-go="${state.role}/platform">${icon('globe')}Explore Candex${icon('external')}</button><div class="support-box">${icon('heart')}<h3>Care without barriers.</h3><p>Support for every step, wherever you are.</p><button class="text-btn" data-action="support">Find support ${icon('arrow')}</button></div><div class="profile"><span class="avatar">${care?'EK':'AL'}</span><div><strong>${care?'Dr. Emilia Koski':'Aino Lehtinen'}</strong><small>${care?'Clinician · demo account':'Patient · demo account'}</small></div></div></div></aside><button class="mobile-scrim" data-action="menu" aria-label="Close navigation"></button><div class="app-body"><header class="topbar"><button class="mobile-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb">${care?'Care team':'My health'}${icon('chevron')}<span>${viewTitles[state.view]}</span></div><div class="top-actions"><div class="role-switch" role="group" aria-label="Choose interface"><button data-go="patient/overview" class="${!care?'selected':''}" aria-pressed="${!care}">${icon('user')}Patient</button><button data-go="care/overview" class="${care?'selected':''}" aria-pressed="${care}">${icon('doctor')}Doctor</button></div><button class="access-btn" data-action="access">${icon('access')}<span>Accessibility</span></button><button class="icon-btn" data-action="notifications" aria-label="View notifications">${icon('bell')}<span class="notification-dot"></span></button></div></header><main class="content" id="main">${viewContent()}<footer class="site-footer"><span>© 2026 Candex · No patient left behind.</span><span class="footer-status"><span class="status-dot"></span>Concept environment · Fictional data</span></footer></main></div>`;
 if(focus){$('#page-title')?.focus({preventScroll:true});window.scrollTo(0,0);}
 if(state.view==='patients') filterPatients();

}
function viewContent(){const views={overview:state.role==='care'?careOverview:patientOverview,health:healthView,pathway:pathwayView,records:recordsView,messages:messagesView,patients:patientsView,scan:scanView,reports:reportsView,analytics:analyticsView,agents:agentsView,platform:platformView};return (views[state.view]||patientOverview)();}
function patientOverview(){return `${heading('A clearer path. Together.','Welcome, Aino. Let’s take your next step with confidence.','Your care, at a glance',`<div class="date-chip">${icon('calendar')}Wednesday, 18 November · Sample day</div>`)}<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="hero-tag">${icon('heart')}Every person. Every cancer. Every step.</div><h2 id="hero-title">No patient<br>left behind.</h2><p>Understand your health, connect with your care team, and see what comes next. All in one place.</p>${goButton('health',state.health?'Review your health check':'Start your health check',true)}</div><div class="hero-art"><img src="care-emblem.svg" alt="A purple cancer awareness ribbon surrounded by a circle of care"><div class="art-label">${icon('shield')}Built around you</div></div></section><section class="stats-row" aria-label="Your care summary"><div class="stat-card"><div class="stat-icon">${icon('heart')}</div><div><small>Your health check</small><strong>${state.health?'Ready for review':'A little about you'}</strong><span class="mini">${state.health?'Summary prepared in this session':'About 3 minutes to complete'}</span></div></div><div class="stat-card"><div class="stat-icon">${icon('route')}</div><div><small>Your care pathway</small><strong>Review in progress</strong><span class="mini">Your team is here to guide you</span></div></div><div class="stat-card"><div class="stat-icon">${icon('calendar')}</div><div><small>Next appointment</small><strong>18 Nov · 10:30</strong><span class="mini">Video consultation · Sample</span></div></div></section><div class="two-col"><section class="card"><div class="card-head"><h2>Your next steps, made clear</h2>${badge('Step 2 of 4')}</div>${journey()}<div class="journey-note">${icon('info')}<p>Your care team reviews your information before recommending the right next step for you.</p></div><div class="card-footer"><span class="muted" style="font-size:.69rem">You don’t have to navigate this alone.</span>${goButton('pathway','View my pathway')}</div></section><section class="card"><div class="card-head"><h2>Your next appointment</h2>${badge('Sample booking','neutral')}</div><div class="appointment"><div class="date-block"><small>Nov</small><strong>18</strong></div><div><h3>A conversation about your care</h3><p>Dr. Emilia Koski · Care team</p><div class="appt-meta">${icon('clock')}10:30–11:00 · Finland time</div><div class="appt-meta">${icon('video')}Video consultation</div></div></div><div class="card-footer"><button class="text-btn" data-action="appointment">Appointment details${icon('arrow')}</button><button class="text-btn" data-action="reminder">${icon(state.reminder?'check':'bell')}${state.reminder?'Reminder set':'Set reminder'}</button></div></section></div><div class="section-line"><h2>A little support goes a long way</h2><span>Everything you need, in one place</span></div><div class="bottom-grid"><article class="action-card"><div class="action-icon">${icon('file')}</div><h3>Your information, understood</h3><p>View example records and understand what your care team is reviewing.</p>${goButton('records','Explore my records')}</article><article class="action-card"><div class="action-icon">${icon('chat')}</div><h3>A question is a good place to start</h3><p>Prepare questions and see how a secure conversation with your team could work.</p>${goButton('messages','Talk to my care team')}</article><article class="action-card"><div class="action-icon">${icon('sparkle')}</div><h3>Meet your Candex guide</h3><p>Find your way with a private, open-source AI guide that runs in your browser.</p>${goButton('agents','Ask the care guide')}</article></div><div class="concept-strip">${icon('globe')}<div><strong>Better care, wherever home is.</strong><p>Connecting patients, clinicians and research across Finland.</p></div>${goButton('platform','Explore the idea')}</div>`;}
function journey(){return `<div class="journey" aria-label="Care pathway: step 2, clinical review"><div class="journey-step done"><span class="step-circle">${icon('check')}</span><strong>Share your story</strong><span>Health information</span></div><div class="journey-step current"><span class="step-circle">2</span><strong>Clinical review</strong><span>You are here</span></div><div class="journey-step"><span class="step-circle">3</span><strong>Next steps</strong><span>Tests, if needed</span></div><div class="journey-step"><span class="step-circle">4</span><strong>Ongoing support</strong><span>Follow-up & care</span></div></div>`;}
function healthView(){const h=state.health||{};return `${heading('Your story matters.','A simple way to prepare for a conversation with your care team.','Patient health check')}${demoNotice('Try the health check with fictional information only. This demo does not calculate cancer risk or provide a diagnosis.')}<div class="two-col"><section class="card"><div class="card-head"><h2>Tell us a little about your health</h2>${badge('About 3 minutes')}</div><form id="health-form"><h3 class="form-section">Your health and history</h3><div class="form-grid"><div class="field"><label for="age">Age</label><input id="age" name="age" type="number" min="18" max="120" required value="${esc(h.age||'')}" placeholder="e.g. 58"></div><div class="field"><label for="focus">Care area</label><select id="focus" name="focus">${['General concern','Lung','Breast','Colorectal','Prostate','Skin','Other / unsure'].map(v=>`<option ${h.focus===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="symptoms">What would you like to discuss?</label><select id="symptoms" name="symptoms">${['A new or persistent symptom', 'A screening invitation', 'Family history', 'An existing referral', 'General information'].map(v=>`<option ${h.symptoms===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="duration">How long has this been on your mind?</label><select id="duration" name="duration">${['Less than 2 weeks', '2–3 weeks', 'More than 3 weeks', 'Not applicable'].map(v=>`<option ${h.duration===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="smoking">Smoking history</label><select id="smoking" name="smoking">${['Prefer not to say', 'Never smoked', 'Previously smoked', 'Currently smoke'].map(v=>`<option ${h.smoking===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="family">Family history of cancer</label><select id="family" name="family">${['Not sure / prefer not to say', 'No known family history', 'Yes, a close relative'].map(v=>`<option ${h.family===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field span2"><label for="notes">Anything else you would like your team to know? (optional)</label><textarea id="notes" name="notes" maxlength="1500" placeholder="For example, a change you’ve noticed or a question you want to ask.">${esc(h.notes||'')}</textarea></div></div><h3 class="form-section space-top">Care that works for your life</h3><div class="form-grid"><div class="field"><label for="region">Region (optional)</label><select id="region" name="region">${['Prefer not to say', 'Uusimaa', 'Pirkanmaa', 'Lapland', 'North Savo', 'Other Finnish region', 'Outside Finland'].map(v=>`<option ${h.region===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="contact">Preferred consultation</label><select id="contact" name="contact">${['Video consultation', 'Phone call', 'In person'].map(v=>`<option ${h.contact===v?'selected':''}>${v}</option>`).join('')}</select></div></div><label class="check-row"><input type="checkbox" name="support" ${h.support?'checked':''}>I would like help with travel, language, technology or the cost of accessing care.</label><div class="form-actions"><small>Kept in this session only. Nothing is sent.</small><button type="submit" class="button">Prepare my summary${icon('arrow')}</button></div></form></section><aside class="stack"><div class="info-panel">${icon('shield')}<h3>You’re in control</h3><p>Share only what feels comfortable. Access needs help the team plan support; they are not treated as signs of cancer.</p><h3>What happens next?</h3><ul><li>A structured summary brings your information together.</li><li>In a connected service, a clinician would review it.</li><li>Your clinician decides whether tests or follow-up are needed.</li></ul></div><div class="card"><h3>If you need help now</h3><p class="subhead" style="margin-bottom:0;font-size:.77rem">Do not wait for an online review if you feel seriously unwell. In Finland, call <a href="tel:112">112</a> for an emergency or <a href="tel:116117">116117</a> for urgent medical advice.</p></div></aside></div>`;}
function pathwayView(){return `${heading('Know what comes next.','A shared view of your care, with a person responsible at every step.','Your care pathway')}${demoNotice()}<div class="two-col"><section class="card"><div class="card-head"><h2>Your example pathway</h2>${badge('Lung care example')}</div>${journey()}<div class="timeline"><div class="timeline-entry"><span class="step-circle">${icon('check')}</span><div><small>12 November 2026 · Completed</small><h3>Your information is in one place</h3><p>Health history, symptoms and your preferences help prepare the review.</p>${goButton('health','Review your health check')}</div></div><div class="timeline-entry"><span class="step-circle">${icon('doctor')}</span><div><small>Current step · Dr. Emilia Koski</small><h3>A clinician reviews your information</h3><p>Imaging and previous records are reviewed together. An AI suggestion would always need clinical review.</p>${badge('Review in progress')}</div></div><div class="timeline-entry"><span class="step-circle">3</span><div><small>Decided together</small><h3>The right next step for you</h3><p>Options may include monitoring, further imaging, a specialist appointment or tests such as a biopsy. A finding does not automatically mean cancer.</p></div></div><div class="timeline-entry"><span class="step-circle">4</span><div><small>Your care team stays with you</small><h3>Follow-up without falling through the gaps</h3><p>Track agreed next steps, reminders and questions. The doctor’s workspace highlights overdue actions.</p>${goButton('messages','Ask your team a question')}</div></div></div></section><aside class="stack"><section class="card"><div class="card-head"><h2>Your care coordinator</h2>${icon('heart')}</div><div class="patient-mini"><span class="avatar">EL</span><div><h3>Elina Lahti</h3><p style="font-size:.73rem">Cancer care nurse · Example team</p></div></div><p class="subhead" style="font-size:.77rem;margin-bottom:16px">A named point of contact to help you understand your pathway and find the support you need.</p>${goButton('messages','Prepare a message')}</section><div class="info-panel"><h3>Distance shouldn’t decide your care.</h3><p>Video and phone appointments, travel support needs and clear follow-up reminders are built into the concept.</p><button class="text-btn space-top" data-action="access-support">Explore access support${icon('arrow')}</button></div></aside></div>`;}
function recordsView(){return `${heading('Your information. Your choice.','Understand your records and choose how your information could support better care.','Records & preferences')}${demoNotice()}<div class="two-col"><section class="card"><div class="card-head"><h2>Example care records</h2>${badge('3 records','neutral')}</div>${[['file','Health check summary',state.health?'Prepared in this session':'Not completed yet','summary'],['scan','Imaging review · lung pilot','14 Nov 2026 · Awaiting clinician review','scan-record'],['file','Consultation preparation','18 Nov 2026 · Questions for your team','prep']].map(([i,t,s,a])=>`<div class="record-row"><span class="record-icon">${icon(i)}</span><div><h3>${t}</h3><p>${s}</p></div><button class="text-btn" data-action="${a}">View${icon('arrow')}</button></div>`).join('')}<div class="notice">My Kanta and hospital imaging connections are proposed integrations. No records have been retrieved from Kanta or a hospital.</div></section><aside class="stack"><section class="card"><div class="card-head"><h2>Research, with your permission</h2>${icon('leaf')}</div><p style="font-size:.78rem">The idea: collect structured, appropriately governed data to study delays, care quality and inequalities.</p><label class="check-row space-top"><input type="checkbox" id="research-consent" ${state.consent?'checked':''}>Try enabling optional research participation in this demo.</label><p style="font-size:.69rem">A real service would require a separate consent process, privacy information and appropriate legal permissions. Nothing is shared here.</p><button class="text-btn space-top" data-action="research-details">What would be collected?${icon('arrow')}</button></section><section class="card"><h3>Session privacy</h3><p class="subhead" style="font-size:.75rem;margin:10px 0 15px">Health-check answers, draft messages and preferences stay in this page session. Reloading clears them.</p><button class="text-btn" data-action="clear">Clear my demo information${icon('arrow')}</button></section></aside></div>`;}
function messagesView(){return `${heading('A conversation starts here.','Prepare your questions in a space designed to feel approachable.','Your care team')}${demoNotice('Messaging demonstration. Your drafts stay in this session and are not sent to a clinician.')}<div class="two-col"><section class="card"><div class="card-head"><div class="patient-mini"><span class="avatar">EL</span><div><h3>Elina · Your care coordinator</h3><p style="font-size:.69rem">Example conversation</p></div></div>${badge('Demo')}</div><div class="chat-message">Hello Aino. Before your consultation, it can help to write down anything you’ve noticed and the questions you’d like us to talk through. You can also tell us if a phone call would be easier than video.<div class="chat-meta">Example care team message · 09:15</div></div>${state.messages.map(m=>`<div class="chat-message mine">${esc(m)}<div class="chat-meta">Your draft · Not sent</div></div>`).join('')}<form id="message-form"><div class="field"><label for="message">Your message</label><textarea id="message" name="message" required maxlength="1500" placeholder="What would you like to ask your care team?"></textarea></div><div class="form-actions"><small>This is a draft, not a monitored clinical channel.</small><button class="button" type="submit">Save demo draft${icon('arrow')}</button></div></form></section><aside class="info-panel"><h3>Not sure where to start?</h3><p>These questions may help you prepare.</p><ul><li>What is the purpose of the next test?</li><li>When should I expect an update?</li><li>Who can I contact if something changes?</li><li>Can we arrange a phone appointment?</li></ul>${goButton('agents','Ask the Candex guide')}</aside></div>`;}
function careOverview(){return `${heading('Every pathway. A clear next step.','Welcome, Dr. Koski. Here’s where your team can make a difference today.','Clinical workspace',goButton('patients','Open worklist',true))}${demoNotice()}<div class="metric-grid"><div class="metric"><p>Awaiting clinical review</p><strong>${4-state.reviewed.size}</strong><small>Sample worklist</small></div><div class="metric"><p>Priority cases</p><strong>${patients.filter(p=>p.priority==='Priority review'&&!state.reviewed.has(p.id)).length}</strong><small>Clinician-defined demo priorities</small></div><div class="metric"><p>Follow-up completion</p><strong>91%</strong><small>Illustrative cohort</small></div><div class="metric"><p>Median time to review</p><strong>18 h</strong><small>Illustrative cohort</small></div></div><div class="two-col"><section class="card"><div class="card-head"><h2>Patients needing your attention</h2>${goButton('patients','View all')}</div>${patients.filter(p=>p.priority==='Priority review').map(p=>`<div class="record-row"><span class="avatar">${p.initials}</span><div><h3>${p.name} <span class="muted" style="font-weight:400">· ${p.age}</span></h3><p>${p.type} pathway · ${p.reason}</p></div><button class="text-btn" data-case="${p.id}">${state.reviewed.has(p.id)?'Reviewed':'Review'}${icon('arrow')}</button></div>`).join('')}<div class="notice">Clinical urgency is not scored by socioeconomic status or geography. Access barriers are tracked separately to organise support.</div></section><section class="card"><div class="card-head"><h2>Close the follow-up gap</h2>${badge('1 action due','amber')}</div><div class="appointment"><div class="date-block"><small>Due</small><strong>18</strong></div><div><h3>Sara Niemi · Breast pathway</h3><p>Confirm specialist appointment and patient contact preference.</p><div class="appt-meta">${icon('location')}Uusimaa · Remote consultation preferred</div></div></div><div class="card-footer"><span class="muted" style="font-size:.7rem">Example workflow alert</span><button class="text-btn" data-action="followup">Manage follow-up${icon('arrow')}</button></div></section></div><div class="section-line"><h2>Connected support for your clinical workflow</h2><span>Clinician-led by design</span></div><div class="bottom-grid"><article class="action-card"><div class="action-icon">${icon('scan')}</div><h3>Imaging, in context</h3><p>Explore annotations, quality checks and comparison in the lung pilot example.</p>${goButton('scan','Open imaging review')}</article><article class="action-card"><div class="action-icon">${icon('sparkle')}</div><h3>Specialist agent workspace</h3><p>See where MedRAX, mAIstro and multi-agent review fit into the workflow.</p>${goButton('agents','Explore agent tools')}</article><article class="action-card"><div class="action-icon">${icon('chart')}</div><h3>Make inequalities visible</h3><p>Track delays, follow-up, data quality and differences across regions.</p>${goButton('analytics','View quality & equity')}</article></div><div class="concept-strip">${icon('shield')}<div><strong>AI supports the decision. The clinician makes it.</strong><p>Every suggested finding, report and pathway requires professional review.</p></div>${goButton('platform','Our approach')}</div>`;}
function patientRows(){return patients.map(p=>`<tr data-patient-row data-text="${esc((p.name+' '+p.id+' '+p.type+' '+p.region).toLowerCase())}" data-priority="${p.priority}"><td><div class="patient-mini"><span class="avatar">${p.initials}</span><div><strong>${p.name}</strong><small>${p.id} · ${p.age} years</small></div></div></td><td>${p.type}<small>${p.region}</small></td><td>${badge(state.reviewed.has(p.id)?'Reviewed':p.priority,state.reviewed.has(p.id)?'':p.priority==='Priority review'?'amber':'neutral')}<small style="margin-top:5px">${p.reason}</small></td><td>${state.followups[p.id]?'Follow-up prepared':state.reviewed.has(p.id)?'Reviewed in this session':p.status}</td><td><button class="text-btn" data-case="${p.id}">Open${icon('arrow')}</button></td></tr>`).join('');}
function patientsView(){return `${heading('A worklist with people at its heart.','See the clinical need, the next action and the access support behind every referral.','Patient worklist')}${demoNotice()}<div class="filter-row"><div class="search">${icon('search')}<label class="sr-only" for="patient-search">Search patients, care areas or regions</label><input id="patient-search" placeholder="Search name, care area or region" value="${esc(state.search)}"></div><label class="sr-only" for="priority-filter">Filter by review priority</label><select id="priority-filter"><option value="all">All priorities</option><option value="Priority review" ${state.filter==='Priority review'?'selected':''}>Priority review</option><option value="Routine review" ${state.filter==='Routine review'?'selected':''}>Routine review</option></select><span id="result-count" class="muted" style="font-size:.73rem" role="status">4 patients</span></div><section class="card table-card"><div class="table-wrap"><table><caption class="sr-only">Fictional multi-cancer patient worklist</caption><thead><tr><th>Patient</th><th>Care pathway</th><th>Review priority & reason</th><th>Status</th><th>Action</th></tr></thead><tbody>${patientRows()}</tbody></table></div><p id="no-results" class="empty" hidden>No patients match this search.</p></section><div class="notice" style="margin-bottom:24px">Candex is designed for all cancer pathways. The PDF’s lung workflow is the imaging demonstration; breast, colorectal and prostate entries illustrate the shared care-coordination model.</div>`;}
function filterPatients(){let count=0;document.querySelectorAll('[data-patient-row]').forEach(row=>{const show=row.dataset.text.includes(state.search.toLowerCase())&&(state.filter==='all'||row.dataset.priority===state.filter);row.hidden=!show;if(show)count++;});if($('#result-count'))$('#result-count').textContent=`${count} patient${count===1?'':'s'}`;if($('#no-results'))$('#no-results').hidden=count>0;}
function sampleScan(prior=false){return `<svg viewBox="0 0 400 320" role="img" aria-label="Schematic chest cross-section, not a medical image. ${prior?'Prior example':'Current example'} with illustrative nodule marker."><defs><radialGradient id="body"><stop stop-color="#a09baf"/><stop offset=".8" stop-color="#7c788b"/><stop offset="1" stop-color="#afa7b8"/></radialGradient><radialGradient id="lung"><stop stop-color="#24212e"/><stop offset="1" stop-color="#393441"/></radialGradient></defs><ellipse cx="200" cy="161" rx="154" ry="127" fill="#494151"/><ellipse cx="200" cy="158" rx="143" ry="116" fill="url(#body)"/><path d="M173 71C137 42 79 84 80 156c-1 68 35 93 72 82 24-8 20-38 29-57 9-20 10-46 4-67z" fill="url(#lung)"/><path d="M226 70c39-25 94 13 95 84 1 71-34 97-72 83-20-7-16-38-26-57-9-20-11-46-5-67z" fill="url(#lung)"/><path d="M199 92v58m0-29-54 51m54-33 57 40m-95-22-28-2m27 2 1 28m79-20 28-10m-27 10 5 22m-111-16-20 16m157-10 13 16" stroke="#898093" stroke-width="6" stroke-linecap="round" fill="none"/><ellipse cx="202" cy="205" rx="21" ry="28" fill="#b9b1bf"/><ellipse cx="202" cy="205" rx="10" ry="15" fill="#70647e"/><ellipse cx="196" cy="155" rx="22" ry="34" fill="#aca3b3"/><circle cx="124" cy="130" r="${prior?5:7}" fill="#b9b0c7"/>${state.overlay?`<circle cx="124" cy="130" r="20" fill="none" stroke="#d8aff5" stroke-width="1.5" stroke-dasharray="4 3"/><path d="M142 122l26-24h65" stroke="#d8aff5" fill="none"/><text x="172" y="91" fill="#e5c6fa" font-size="10" font-family="sans-serif">Example finding A</text>`:''}<text x="48" y="33" fill="#ac9dbb" font-size="10" font-family="sans-serif">R</text><text x="340" y="33" fill="#ac9dbb" font-size="10" font-family="sans-serif">L</text><text x="200" y="308" text-anchor="middle" fill="#ac9dbb" font-size="10" font-family="sans-serif">SCHEMATIC · NOT FOR CLINICAL USE</text></svg>`;}
function scanView(){const p=patients.find(p=>p.id===state.selected)||patients[0];return `${heading('A second look. A fuller picture.','Explore the lung pilot’s imaging review and clinician-led decision support.','Clinical imaging',`<button class="button secondary" data-action="upload">${icon('upload')}Try a local file</button>`)}${demoNotice('Lung pilot · The illustration, measurements and findings below are prewritten examples. No imaging AI has run. MedRAX supports chest X-ray workflows, not this schematic CT example.')}<div class="scan-layout"><div class="stack"><section class="scan-viewer"><div class="scan-toolbar"><span>${p.id==='CX-1042'?'CX-1042 · Aino Lehtinen':'CX-1042 · Lung pilot sample'}</span>${badge(state.scanPrior?'Prior · 14 Aug 2026':'Current · 14 Nov 2026')}</div><div class="scan-stage">${sampleScan(state.scanPrior)}</div><p class="scan-caption">Illustrated chest cross-section · Example series 3</p><div class="scan-controls"><button data-action="current-scan" class="${!state.scanPrior?'active':''}">Current example</button><button data-action="prior-scan" class="${state.scanPrior?'active':''}">Prior example</button><label><input type="checkbox" id="overlay" ${state.overlay?'checked':''}>Show annotation</label></div></section><section class="card"><div class="card-head"><h2>Quality & comparison</h2>${badge('Sample assessment','neutral')}</div><div class="data-line"><span>Image quality</span><strong>Acceptable · Example only</strong></div><div class="data-line"><span>Finding A · Current diameter</span><strong>8 mm · Illustrative</strong></div><div class="data-line"><span>Prior example diameter</span><strong>6 mm · Illustrative</strong></div><div class="data-line"><span>Interval</span><strong>3 months</strong></div><p style="font-size:.7rem;margin-top:13px">Real comparison requires compatible scans, acquisition checks, measurement uncertainty and specialist interpretation.</p></section></div><div class="stack"><section class="card"><div class="card-head"><h2>Review notes</h2>${badge('Needs clinician review','amber')}</div><ul class="findings"><li><strong><span class="finding-dot"></span>Example finding A</strong><p>Illustrative focal change in the right lung. Confirm on the source study and compare with previous imaging.</p></li><li><strong>Clinical context</strong><p>58 years · Prior smoking history · Family history to confirm. Clinical information is fictional.</p></li><li><strong>Clinician responsibility</strong><p>AI cannot confirm cancer. Additional imaging, specialist assessment or pathology may be needed.</p></li></ul>${goButton('agents','Explore medical-agent integration')}</section><section class="card"><div class="card-head"><h2>Structured decision support</h2>${icon('doctor')}</div><form id="decision-form"><div class="field"><label for="decision">What is the next clinical action?</label><select id="decision" name="decision"><option value="">Select for this demonstration</option><option>Surveillance / repeat imaging</option><option>Further imaging or specialist investigation</option><option>Biopsy / pathology assessment</option><option>Discuss at multidisciplinary team review</option></select></div><div class="field space-top"><label for="rationale">Review notes</label><textarea id="rationale" name="rationale" placeholder="Record your reasoning. Use fictional details only." maxlength="1500"></textarea></div><button class="button space-top" type="submit">Prepare review draft${icon('arrow')}</button></form></section></div></div><div class="space-top" style="margin-bottom:24px">${goButton('reports','Open structured report')}</div>`;}
function reportsView(){return `${heading('Less repetition. More clinical context.','Bring findings, history and next steps into a report a clinician can review.','Clinical reporting')}${demoNotice('Structured report demonstration. The draft uses sample text and your session notes; it is not generated by a medical AI.')}<div class="two-col"><section class="card"><div class="card-head"><h2>Draft clinical report</h2>${badge('Unapproved draft','amber')}</div><form id="report-form"><div class="form-grid"><div class="field"><label for="report-patient">Patient reference</label><input id="report-patient" name="patient" value="${esc(state.report?.patient||'CX-1042 · Fictional lung pilot')}"></div><div class="field"><label for="report-type">Care pathway</label><select id="report-type" name="type">${['Lung','Breast','Colorectal','Prostate','Other cancer pathway'].map(t=>`<option ${state.report?.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field span2"><label for="report-findings">Findings for review</label><textarea id="report-findings" name="findings" required>${esc(state.report?.findings||'Sample imaging illustration shows finding A. Example measurements: current 8 mm; previous 6 mm. These are fictional values, not AI measurements.')}</textarea></div><div class="field span2"><label for="report-plan">Proposed next step</label><textarea id="report-plan" name="plan" required>${esc(state.report?.plan||'Clinician to review source imaging, confirm relevant history and determine the appropriate follow-up. No diagnosis has been established.')}</textarea></div></div><label class="check-row space-top"><input type="checkbox" required>I understand this creates a demonstration draft, not a signed clinical report.</label><div class="form-actions"><button class="button secondary" type="button" data-action="agent-report">${icon('sparkle')}Agent-assisted workflow</button><button class="button" type="submit">Preview & download${icon('arrow')}</button></div></form></section><aside class="stack"><div class="info-panel">${icon('file')}<h3>A consistent structure</h3><ul><li>Patient reference and clinical context</li><li>Image quality and comparison</li><li>Findings, uncertainty and limitations</li><li>Clinician-approved recommendations</li><li>Named owner and follow-up deadline</li></ul></div><section class="card"><h3>Keep the person in the pathway</h3><p class="subhead" style="font-size:.77rem;margin:10px 0 15px">Reports should lead to an action, a responsible team member and a clear explanation for the patient.</p>${goButton('pathway','See the patient pathway',false,'patient')}</section></aside></div>`;}
const metrics=[['Time to first review','18 h','Scan completion → radiologist review'],['Time to diagnosis','24 d','Suspicious finding → confirmed diagnosis'],['Detection sensitivity','92%','Detected / confirmed cancers in a labelled test cohort'],['False-positive rate','8%','False-positive scans / all negative scans'],['Follow-up completion','91%','On-time completed / due follow-ups'],['Regional waiting-time gap','11 d','Longest − shortest regional median'],['Demographic sensitivity gap','4 pp','Largest group sensitivity difference'],['Research completeness','87%','Complete / eligible structured records']];
function analyticsView(){return `${heading('Measure the gaps. Improve the pathway.','A quality and equity view designed to help teams learn and act.','Quality & equity',`<button class="button secondary" data-action="export-metrics">${icon('download')}Export sample data</button>`)}${demoNotice('All metrics and regional values are invented examples, not evaluated Candex performance or Finnish healthcare statistics.')}<div class="metric-grid">${metrics.map(([t,v,s])=>`<article class="metric"><p>${t}</p><strong>${v}</strong><small>${s}</small></article>`).join('')}</div><div class="two-col"><section class="card"><div class="card-head"><h2>Time to diagnosis by region</h2>${badge('Sample · median days','neutral')}</div>${[['Uusimaa',21],['Pirkanmaa',24],['North Savo',27],['Lapland',32]].map(([r,n])=>`<div class="bar-row"><span>${r}</span><div class="bar-track"><div class="bar-fill" style="width:${n/35*100}%"></div></div><strong>${n} days</strong></div>`).join('')}<p style="font-size:.71rem;margin-top:18px">In a real analysis, report cohort size, case mix, missing data and uncertainty before comparing regions.</p></section><section class="card"><div class="card-head"><h2>Research-ready, responsibly</h2>${badge('87% complete')}</div><p style="font-size:.78rem">Structured records connect pathway events with outcomes and access needs, subject to consent and lawful permissions.</p><div class="completeness" role="img" aria-label="Example research data completeness: 87 percent"><span style="width:87%"></span></div><div class="data-line"><span>Clinical / imaging fields</span><strong>94% · Sample</strong></div><div class="data-line"><span>Follow-up outcomes</span><strong>83% · Sample</strong></div><div class="data-line"><span>Optional equity fields</span><strong>74% · Sample</strong></div><div class="card-footer"><button class="text-btn" data-action="pdsa">Build a PDSA review${icon('arrow')}</button>${goButton('records','Patient consent view',false,'patient')}</div></section></div><section class="card" style="margin-bottom:24px"><h2>Performance for every patient group</h2><p class="subhead" style="margin:10px 0 15px;font-size:.77rem">Evaluate sensitivity and false-positive rates by appropriately defined groups. Small cohorts should be suppressed and differences assessed with uncertainty.</p><div class="table-wrap"><table><caption class="sr-only">Fictional demographic model evaluation</caption><thead><tr><th>Illustrative evaluation group</th><th>Labelled cohort</th><th>Sensitivity</th><th>False-positive rate</th><th>Interpretation</th></tr></thead><tbody><tr><td>Age 50–64</td><td>250</td><td>94%</td><td>7%</td><td>Example only</td></tr><tr><td>Age 65–79</td><td>250</td><td>90%</td><td>9%</td><td>Investigate a sample 4 pp gap</td></tr><tr><td>Small access-needs subgroup</td><td>Suppressed</td><td>—</td><td>—</td><td>Insufficient data</td></tr></tbody></table></div></section>`;}
function agentsView(){return `${heading('Purposeful AI. Human accountability.','Open-source support for understanding the platform, research and clinical workflows.','Candex intelligence')}${demoNotice('The browser-based Candex guide can run a real open-source language model for semantic search. Medical frameworks below require separate Python/model services and are not connected.')}<div class="tabs" role="group" aria-label="Agent workspace"><button class="${state.agent==='guide'?'active':''}" data-agent="guide">Candex guide</button><button class="${state.agent==='medical'?'active':''}" data-agent="medical">Medical agents</button></div>${state.agent==='guide'?guideView():medicalAgentsView()}`;}
function guideView(){return `<div class="two-col"><section class="card"><div class="card-head"><h2>Your Candex guide</h2>${badge('Open-source · Browser-local')}</div><p style="font-size:.79rem">Ask how to use a feature or find your next step in the platform. The guide matches your question to reviewed explanations; it does not assess symptoms or give medical advice.</p><div class="notice" id="model-status" role="status">AI is off. Enable it to download a small embedding model (approximately 23 MB) from Hugging Face. Your questions are processed locally; the model host receives the download request.</div><div class="button-row space-top"><button class="button" data-action="enable-ai" id="enable-ai">${icon('sparkle')}${window.candexGuide?.ready?'AI is ready':'Enable local AI guide'}</button><button class="button secondary" data-action="guide-examples">Browse topics without AI</button></div><form id="guide-form" class="space-top"><div class="field"><label for="guide-question">What can we help you find?</label><input id="guide-question" name="question" required maxlength="500" placeholder="e.g. How do I compare previous scans?"></div><button class="button space-top" type="submit">Find guidance${icon('arrow')}</button></form><div id="guide-answer" aria-live="polite"></div></section><aside class="stack"><div class="info-panel">${icon('lock')}<h3>Private by design</h3><p>This agent uses Transformers.js and the open-source all-MiniLM-L6-v2 model to find relevant, approved platform content.</p><p>It selects a topic and suggests an action. It cannot diagnose, interpret images, contact a doctor or alter a care plan.</p><a class="text-btn space-top" href="https://github.com/huggingface/transformers.js" target="_blank" rel="noopener">View inference library${icon('external')}</a><br><a class="text-btn" href="https://huggingface.co/Xenova/all-MiniLM-L6-v2" target="_blank" rel="noopener">View open-source model${icon('external')}</a></div><section class="card"><h3>Try asking</h3>${['How do I prepare for an appointment?','Where can I see regional differences?','How is research consent managed?'].map(t=>`<button class="topic-prompt" data-prompt="${esc(t)}">${t}${icon('arrow')}</button>`).join('')}</section></aside></div>`;}
function medicalAgentsView(){return `<div class="feature-grid" style="margin-top:0">${[
 ['MedRAX','Chest X-ray research agent','Tool-based chest X-ray review and multi-step reasoning. Relevant to the lung pilot; it is not an all-cancer or CT diagnostic engine.','Apache 2.0','https://github.com/bowang-lab/MedRAX'],
 ['mAIstro','Radiomics & research workflows','Coordinate feature extraction, segmentation and research analysis through specialist tools in a separate Python environment.','Apache 2.0','https://github.com/eltzanis/mAIstro'],
 ['Radiology Swarm','Multi-role review & reporting','A source framework for sequential image review and report drafting. Requires engineering review and repair before use; no clinical validation is assumed.','MIT','https://github.com/The-Swarm-Corporation/radiology-swarm']
].map(([name,role,desc,license,link])=>`<article class="feature-card"><div class="feature-number">${license} · OPEN SOURCE</div><h3>${name}</h3>${badge('Not connected','neutral')}<h4 style="font-size:.77rem;margin:16px 0 8px">${role}</h4><p>${desc}</p><a class="text-btn" href="${link}" target="_blank" rel="noopener">Explore source${icon('external')}</a></article>`).join('')}</div><div class="two-col"><section class="card"><div class="card-head"><h2>One coordinated review workflow</h2>${badge('Illustrative orchestration','neutral')}</div><div class="workflow">${['Patient context','Quality check','Specialist tools','Compare & extract','Clinician review','Report & follow-up'].map((s,i)=>`<span><b>${i+1}</b>${s}</span>`).join('')}</div><p style="font-size:.77rem">Use the working structured tools now. In a live implementation, medical agents would supply attributed suggestions to the same review and reporting interfaces.</p><div class="button-row space-top">${goButton('scan','Review lung example',true,'care')}${goButton('reports','Prepare report',false,'care')}</div></section><aside class="card"><div class="card-head"><h2>Live service requirements</h2>${icon('lock')}</div><ul class="simple-list"><li>External Python service, models and suitable compute</li><li>Server-held model credentials and authenticated API</li><li>Approved data handling, consent and clinical governance</li><li>Tool provenance, audit trail and clinician sign-off</li></ul><button class="text-btn" data-action="integration-contract">View integration contract${icon('arrow')}</button></aside></div>`;}
function platformView(){return `${heading('No patient left behind.','The idea, the features and the path from first concern to continuing care.','Meet Candex')}<section class="platform-hero"><div><div class="eyebrow">Every cancer. Every community.</div><h2>Earlier understanding.<br>More connected care.</h2><p>Candex brings patients, clinicians and research into one clearer care pathway. Designed for Finland, it combines accessible support, clinical decision tools and visibility into the gaps in care.</p><div class="button-row space-top">${goButton('overview','Patient experience',true,'patient')}${goButton('overview','Doctor experience',false,'care')}</div></div><img src="care-emblem.svg" alt="Purple cancer awareness ribbon, representing support across cancer types"></section><div class="notice">An all-cancer concept with a detailed lung-care pilot from the original proposal. Clinical AI, Kanta/PACS connections and outcome improvements require implementation and evaluation.</div><div class="section-line space-top"><h2>Explore every part of the idea</h2><span>From a person’s story to better systems</span></div><div class="feature-grid">${[
 ['01','A low-barrier first step','A guided health check captures concerns, history and access preferences without a difficult first conversation.','health','patient'],
 ['02','Imaging in context','Illustrate quality checks, suspicious-region annotations and comparison with previous imaging.','scan','care'],
 ['03','Personalised clinical review','Bring relevant clinical context together. A validated risk model would support, rather than replace, clinical judgement.','patients','care'],
 ['04','Decision support & reports','Structure clinician reasoning and prepare editable drafts with a clear next action.','reports','care'],
 ['05','A pathway that stays connected','Show the patient what happens next while the team tracks responsibility and follow-up.','pathway','patient'],
 ['06','Open-source agent support','Run a local AI platform guide and explore the integration points for specialist medical frameworks.','agents','care'],
 ['07','Quality & equity, visible','Eight proposed indicators cover delays, model performance, regional differences and follow-up.','analytics','care'],
 ['08','Responsible research data','Structured variables, data quality and optional participation support appropriately governed research.','records','patient'],
 ['09','Access by design','Readable text, keyboard-friendly controls, clear language, remote-care preferences and access support.','health','patient']
 ].map(([n,t,p,v,r])=>`<article class="feature-card"><span class="feature-number">${n} / THE CANDEX APPROACH</span><h3>${t}</h3><p>${p}</p>${goButton(v,'Try the feature',false,r)}</article>`).join('')}</div><section class="card" style="margin-bottom:23px"><div class="card-head"><h2>Designed to connect, thoughtfully</h2>${badge('Integration roadmap','neutral')}</div>${[
 ['Kanta / My Kanta','Proposed record exchange with Finland’s national services, subject to eligibility, authentication and interoperability requirements. No connection exists in this demo.','https://www.kanta.fi/en'],
 ['PACS / DICOM / Orthanc','Hospital imaging and DICOMweb could support source-image retrieval and longitudinal review. Orthanc is an open-source DICOM server.','https://www.orthanc-server.com/'],
 ['Research datasets & registries','Public datasets can support research; patient-level register reuse requires appropriate permissions. Finnish Cancer Registry statistics provide context, not access to private records.','https://findata.fi/en/']
 ].map(([t,d,l])=>`<div class="integration-row"><div><h3>${t}</h3><p>${d}</p><a href="${l}" target="_blank" rel="noopener">Learn about the source ${icon('external')}</a></div>${badge('Planned','neutral')}</div>`).join('')}</section><section class="card" style="margin-bottom:24px"><h2>Clear about what this is</h2><details><summary>Is Candex providing real clinical care?</summary><p>No. This is an interactive concept with fictional data. The browser AI guide supports platform navigation only. Clinical findings, priorities, appointments and metrics are examples.</p></details><details><summary>Does the platform cover all cancer types?</summary><p>The shared patient journey, care coordination, reports and analytics are designed for multiple cancer pathways. The detailed imaging example is a lung pilot. Each cancer-specific AI tool would need its own evidence, appropriate data and clinical validation.</p></details><details><summary>How does Candex support rural and underserved patients?</summary><p>The concept captures remote-care preferences and access barriers, provides readable care updates and highlights regional delays. Travel, language and affordability support would be arranged by a connected care service.</p></details><details><summary>What would make the medical AI live?</summary><p>A separately hosted, authenticated Python/model service, appropriate medical-data handling and clinical governance. Open-source code alone is not evidence of safety or effectiveness.</p></details></section>`;}
function showDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!d.open)d.showModal();}
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function download(name,content,type='text/plain'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function summaryHTML(){return state.health?`<div class="report-preview">DEMONSTRATION SUMMARY — NOT SENT\n\nAge: ${esc(state.health.age)}\nCare area: ${esc(state.health.focus)}\nReason: ${esc(state.health.symptoms)}\nDuration: ${esc(state.health.duration)}\nSmoking: ${esc(state.health.smoking)}\nFamily history: ${esc(state.health.family)}\nRegion: ${esc(state.health.region)}\nPreferred contact: ${esc(state.health.contact)}\nAccess support requested: ${state.health.support?'Yes':'No'}\n\nNotes: ${esc(state.health.notes||'None added')}\n\nNo cancer risk score or diagnosis has been calculated.</div><p>In a live service, a clinician would review this information. This summary remains in your session.</p>`:'<p>You haven’t completed a demo health check yet.</p>'+goButton('health','Start health check',true,'patient');}
const actions={
 'menu':()=>{const open=$('#sidebar').classList.toggle('open');$('.mobile-toggle').setAttribute('aria-expanded',String(open));},
 'close-dialog':()=>$('#dialog').close(),
 'access':()=>showDialog('Make Candex work for you',`<p>Adjust the display to your preference. These settings apply throughout the website.</p><label class="check-row"><input type="checkbox" id="large-text" ${document.documentElement.classList.contains('large-text')?'checked':''}>Larger text</label><label class="check-row"><input type="checkbox" id="high-contrast" ${document.documentElement.classList.contains('high-contrast')?'checked':''}>Higher contrast</label><label class="check-row"><input type="checkbox" id="reduced-motion" ${document.documentElement.classList.contains('reduced-motion')?'checked':''}>Reduce motion</label><p>Use Tab to move between controls, Enter to activate them and Escape to close this window. Your device’s reduced-motion preference is respected.</p>`),
 'notifications':()=>showDialog('Your notifications',`<div class="record-row">${icon('calendar')}<div><h3>Consultation coming up</h3><p>18 November · 10:30 · Fictional appointment</p></div></div><div class="record-row">${icon('file')}<div><h3>Your next step is clinical review</h3><p>Your example pathway is ready to explore.</p></div></div>${goButton('pathway','View pathway',true,'patient')}`),
 'support':()=>showDialog('Support, wherever you are',`<p>Candex is designed to make it easier to ask for help with travel, language, technology or financial barriers.</p><p>In a connected service, your care coordinator would help arrange suitable support. This prototype does not contact a care service.</p>${goButton('health','Add access preferences',true,'patient')}<p>For cancer information and support in Finland, visit <a href="https://www.cancersociety.fi/" target="_blank" rel="noopener">Cancer Society of Finland</a>.</p>`),
 'access-support':()=>actions.support(),
 'appointment':()=>showDialog('Your example consultation',`<div class="appointment"><div class="date-block"><small>Nov</small><strong>18</strong></div><div><h3>18 November 2026 · 10:30–11:00</h3><p>Finland time (EET) · Video consultation</p><p>Dr. Emilia Koski · Fictional care team</p></div></div><h3 class="space-top">A little preparation can help</h3><p>Write down your questions, any changes you’ve noticed and your medicines. You can request a phone call if video is difficult.</p><div class="notice">This is an example appointment. There is no live call or booking.</div><button class="button space-top" data-action="calendar-download">${icon('download')}Download sample calendar event</button>`),
 'reminder':()=>{state.reminder=!state.reminder;render();toast(state.reminder?'Demo reminder enabled for this session. No notification will be sent.':'Demo reminder removed.');},
 'calendar-download':()=>download('candex-example-appointment.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Candex//Concept//EN\r\nBEGIN:VEVENT\r\nUID:candex-demo-20261118@candex.example\r\nDTSTAMP:20261114T080000Z\r\nDTSTART:20261118T083000Z\r\nDTEND:20261118T090000Z\r\nSUMMARY:Candex DEMO consultation - not a real appointment\r\nDESCRIPTION:Fictional calendar example. No appointment is booked.\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n','text/calendar'),
 'summary':()=>showDialog('Your demo health summary',summaryHTML()),
 'scan-record':()=>showDialog('Understanding the imaging example','<p>The lung pilot shows an illustrated chest cross-section with a prewritten example finding. It is not a medical scan or an actual AI result.</p><p>A real report would explain the finding, uncertainty and next steps after clinician review. A finding alone does not confirm cancer.</p>'+goButton('scan','Explore the clinician example',true,'care')),
 'prep':()=>showDialog('Your consultation checklist','<label class="check-row"><input type="checkbox">Write down changes or symptoms you want to discuss.</label><label class="check-row"><input type="checkbox">Prepare questions about tests and next steps.</label><label class="check-row"><input type="checkbox">Have a list of medicines available.</label><label class="check-row"><input type="checkbox">Tell your team if phone or in-person care is easier.</label><p>This is a preparation checklist, not medical advice.</p>'),
 'research-details':()=>showDialog('Research data, explained','<p>The proposed research record includes pathway dates, imaging findings approved by a clinician, follow-up, outcomes and optional access/equity variables.</p><p>Access-related information should support equity analysis and practical help, rather than being treated as a biological cancer-risk factor.</p><p>Real research participation would need clear purposes, an appropriate legal basis, consent where required, access controls and withdrawal information. No research data is collected or shared by this demo.</p>'),
 'clear':()=>{state.health=null;state.messages=[];state.consent=false;state.report=null;state.reminder=false;state.followups={};render();toast('Your session’s demo information has been cleared.');},
 'followup':()=>{const p=state.view==='patients'?(patients.find(p=>p.id===state.selected)||patients[2]):patients[2];const saved=state.followups[p.id];showDialog('Keep a person responsible for the next step',`<p><strong>${esc(p.name)} · ${p.id}</strong><br>Fictional ${p.type.toLowerCase()} care pathway</p><form id="followup-form"><input type="hidden" name="patientId" value="${p.id}"><div class="field"><label for="followup-owner">Responsible person</label><input id="followup-owner" name="owner" required value="${esc(saved?.owner||'Dr. Emilia Koski')}"></div><div class="field space-top"><label for="followup-step">Next action</label><input id="followup-step" name="step" required value="${esc(saved?.step||'Confirm specialist appointment and contact patient')}"></div><button type="submit" class="button space-top">Save demo follow-up${icon('check')}</button></form>`);},
 'current-scan':()=>{state.scanPrior=false;render();},'prior-scan':()=>{state.scanPrior=true;render();},
 'upload':()=>showDialog('Try the local file workflow',`<p>Choose a demonstration image to see its file details. It stays in your browser. No upload, quality assessment or medical AI analysis occurs.</p><p>Use a public or synthetic example, not personal medical information.</p><div class="field space-top"><label for="local-file">Choose a sample image or DICOM file</label><input type="file" id="local-file" accept="image/*,.dcm,.dicom"></div><div id="file-details" role="status"></div>`),
 'agent-report':()=>{state.agent='medical';navigate('care/agents');},
 'export-metrics':()=>download('candex-illustrative-quality-metrics.csv','"Metric","Illustrative value","Definition"\n'+metrics.map(row=>row.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv'),
 'pdsa':()=>showDialog('A quarterly PDSA review',`<div class="report-preview">ILLUSTRATIVE QUALITY-IMPROVEMENT DRAFT\n\nPLAN\nInvestigate the sample 11-day regional waiting-time gap.\n\nDO\nMap referral handoffs and remote-care availability with the local teams.\n\nSTUDY\nCompare time to review, follow-up completion and missing data, adjusting for case mix and small cohorts.\n\nACT\nAgree an owner, a change to test and a review date.\n\nAll figures in this prototype are invented examples.</div><button class="button space-top" data-action="download-pdsa">${icon('download')}Download review template</button>`),
 'download-pdsa':()=>download('candex-pdsa-template.txt','CANDEX — PDSA REVIEW TEMPLATE\n\nPlan: What gap will you investigate?\nDo: What change will you test, and who owns it?\nStudy: What evidence, cohort size and uncertainty will you review?\nAct: What will you adopt, adapt or stop?\n\nUse approved data only. Demo metrics are fictional.'),
 'integration-contract':()=>showDialog('Medical-agent integration contract',`<p>Medical agents must run behind an authenticated server, not in this static website. Do not put model API keys in browser code.</p><div class="report-preview">POST /api/clinical-agent/review\n\nInput: permitted study reference, selected agent, approved clinical context, consent reference\n\nOutput: findings[], tool_calls[], model_version, limitations[], requires_clinician_review: true\n\nRequired: authentication, authorisation, audit logs, timeout, safe failure, clinician sign-off</div><p>Current service status: <strong>Not configured</strong>. Source links and structured workflows are available; no medical-agent request is being made.</p>`),
 'enable-ai':async()=>{const status=$('#model-status'),button=$('#enable-ai');button.disabled=true;status.textContent='Loading open-source library and model. The first load may take a minute.';try{const module=await import('./guide.js');await module.initializeGuide(text=>{if($('#model-status'))$('#model-status').textContent=text;});if($('#model-status'))$('#model-status').textContent='Local AI guide ready. Questions stay in your browser; answers come from reviewed Candex content.';if($('#enable-ai'))$('#enable-ai').textContent='AI guide ready';}catch(e){if($('#model-status'))$('#model-status').textContent='The model could not load on this device or network. You can still browse all guidance topics without AI.';if($('#enable-ai')){$('#enable-ai').disabled=false;$('#enable-ai').textContent='Try loading again';}}},
 'guide-examples':async()=>{const m=await import('./guide.js');showDialog('Browse Candex topics',m.topics.map(t=>`<div class="record-row"><div><h3>${esc(t.title)}</h3><p>${esc(t.answer)}</p>${goButton(t.view,'Open feature',false,t.role)}</div></div>`).join(''));}
};
document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){if($('#dialog').open)$('#dialog').close();navigate(go.dataset.go);return;}const a=e.target.closest('[data-action]');if(a){actions[a.dataset.action]?.();return;}const c=e.target.closest('[data-case]');if(c){state.selected=c.dataset.case;const p=patients.find(p=>p.id===state.selected);if(p.type==='Lung')navigate('care/scan');else showDialog(`${p.name} · ${p.type} pathway`,`<p>${p.id} · ${p.age} years · ${p.region}<br>Fictional patient</p><div class="data-line"><span>Next step</span><strong>${p.status}</strong></div><p>${p.reason}. This example covers care coordination; no cancer-specific imaging model is running.</p><button class="button space-top" data-action="followup">Prepare follow-up${icon('arrow')}</button>`);return;}const agent=e.target.closest('[data-agent]');if(agent){state.agent=agent.dataset.agent;render();return;}const prompt=e.target.closest('[data-prompt]');if(prompt){$('#guide-question').value=prompt.dataset.prompt;$('#guide-question').focus();}});
document.addEventListener('change',e=>{const id=e.target.id;if(['large-text','high-contrast','reduced-motion'].includes(id)){document.documentElement.classList.toggle(id,e.target.checked);try{localStorage.setItem('candex-display',JSON.stringify(['large-text','high-contrast','reduced-motion'].filter(c=>document.documentElement.classList.contains(c))));}catch{}}if(id==='research-consent'){state.consent=e.target.checked;toast(state.consent?'Demo preference enabled. No data is shared.':'Demo research preference disabled.');}if(id==='overlay'){state.overlay=e.target.checked;render();}if(id==='priority-filter'){state.filter=e.target.value;filterPatients();}if(id==='local-file'){const f=e.target.files[0];if(f)$('#file-details').innerHTML=`<div class="notice"><strong>${esc(f.name)}</strong><br>${Math.round(f.size/1024)} KB · ${esc(f.type||'Unspecified file type')}<br>Local selection only. No file has been uploaded or analysed.</div>`;}});
document.addEventListener('input',e=>{if(e.target.id==='patient-search'){state.search=e.target.value;filterPatients();}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));if(form.id==='health-form'){state.health=data;showDialog('Your story, ready for review',summaryHTML()+goButton('pathway','See my next steps',true,'patient'));}if(form.id==='message-form'){state.messages.push(data.message);render();toast('Draft saved in this session. Nothing was sent.');}if(form.id==='decision-form'){if(!data.decision){toast('Choose a demonstration next step first.');return;}state.report={findings:data.rationale||'Illustrative finding A requires review on the original study.',plan:data.decision};state.reviewed.add('CX-1042');showDialog('Clinical review draft prepared','<p>Your example decision and notes have been added to the report draft for this session. This is not a clinical sign-off.</p>'+goButton('reports','Review report draft',true,'care'));}if(form.id==='report-form'){const report=`CANDEX — DEMONSTRATION REPORT\nUNAPPROVED DRAFT · NOT FOR CLINICAL USE\n\nPatient: ${data.patient}\nPathway: ${data.type}\n\nFINDINGS\n${data.findings}\n\nPROPOSED NEXT STEP\n${data.plan}\n\nAll imaging and findings are examples. No medical AI has run.\nClinician review and appropriate clinical evidence are required.`;state.report={...data};state.reportText=report;showDialog('Review your example report',`<div class="report-preview">${esc(report)}</div><button class="button space-top" data-action="download-report">${icon('download')}Download text draft</button>`);}if(form.id==='followup-form'){state.followups[data.patientId]={owner:data.owner,step:data.step};$('#dialog').close();render();toast('Demo follow-up saved for this session. No clinical task was sent.');}if(form.id==='guide-form'){const answer=$('#guide-answer');answer.innerHTML='<div class="notice">Finding the right guidance…</div>';try{const m=await import('./guide.js');const result=await m.findGuidance(data.question);answer.innerHTML=`<div class="notice"><strong>${esc(result.title)}</strong><p style="margin:9px 0">${esc(result.answer)}</p>${goButton(result.view,'Open this feature',false,result.role)}<p style="margin-top:10px;font-size:.65rem">${result.mode==='ai'?'Matched by the local open-source embedding model.':'Topic matching without AI. Enable the local model for semantic matching.'} Platform guidance only.</p></div>`;}catch{answer.innerHTML='<div class="notice">Guidance is temporarily unavailable. Use the navigation to explore each feature.</div>';}}});
actions['download-report']=()=>download('candex-demo-report.txt',state.reportText||'No report prepared.');
try{const prefs=JSON.parse(localStorage.getItem('candex-display')||'[]');for(const c of prefs)if(['large-text','high-contrast','reduced-motion'].includes(c))document.documentElement.classList.add(c);}catch{}
window.addEventListener('hashchange',()=>{getRoute();render(true);});
getRoute();render();
